 it('owns exact compact power state and binds complete original identity without a second optical calculation',()=>{const result=decodeFresnelTrace(wire(fixture()),request,validateFresnelValidation(validation(),request));expect(result.branches[0].initial_state.C).toEqual([.5,.5,0,0]);expect(Object.isFrozen(result.events[0].incident_state.frame)).toBe(true);expect(fresnelResourceBreakdown(result)).toMatchObject({retainedRawBytes:0,retainedResponseTextBytes:0});const original=structuredClone(scene),owned=freezeFresnelScene(original);(original.source.origin_m as unknown as number[])[0]=9;expect(owned.source.origin_m[0]).toBe(0);});
