 it('keeps exact source presets and rejects unsupported source editor or components',()=>{expect(()=>freezeFresnelScene({...scene,source:{...scene.source,direction:[1,0,0]}})).toThrow();expect(()=>freezeFresnelScene({...scene,elements:[{...scene.elements[0],kind:'mirror'}]})).toThrow();expect(()=>freezeFresnelScene({...scene,source:{...scene.source,polarization:'circular' as any}})).toThrow();});
