function changeFirstReflectedStates(g:any,edit:(s:any)=>void):number{const reference=g.branches.find((b:any)=>b.id==='r0.R').initial_state;let count=0;const walk=(v:any):void=>{if(!v||typeof v!=='object')return;if(v.medium_id===reference.medium_id&&v.power_fraction===reference.power_fraction&&Array.isArray(v.C)&&v.frame&&v.numerical_bounds){edit(v);count++;}Object.values(v).forEach(walk);};walk(g);return count;}
describe('W4 genuine dielectric graph metadata regressions',()=>{
 it.each(['R_s','R_p','T_s','T_p'] as const)('checks %s against its signed-complex coefficient and transmission flux representation',channel=>{const g=structuredClone(genuine_normal_slab);g.events[0].interface!.power_fractions[channel]=.5;expect(()=>decodeFresnelTrace(wire(g),{request_id:g.request_id,scene_sha256:g.scene_sha256,scene:g.scene as unknown as FresnelScene})).toThrow(/amplitude\/power channel relationship/);});
 it('does not hide a weak positive pure-channel power behind a unit-size absolute tolerance',()=>{const g=structuredClone(genuine_normal_slab),f=g.events[0].interface!;f.coefficients.r_p=[1e-16,0];f.numerical_bounds.coefficient_intervals[1]=[[1e-16,1e-16],[0,0]];f.power_fractions.R_p=0;expect(()=>decodeFresnelTrace(wire(g),{request_id:g.request_id,scene_sha256:g.scene_sha256,scene:g.scene as unknown as FresnelScene})).toThrow(/amplitude\/power channel relationship/);});
 it('rejects positive amplitude-to-power underflow rather than accepting a rounded algebraic zero',()=>{const g=structuredClone(genuine_normal_slab),f=g.events[0].interface!;f.coefficients.r_p=[1e-200,0];f.numerical_bounds.coefficient_intervals[1]=[[1e-200,1e-200],[0,0]];f.power_fractions.R_p=0;expect(()=>decodeFresnelTrace(wire(g),{request_id:g.request_id,scene_sha256:g.scene_sha256,scene:g.scene as unknown as FresnelScene})).toThrow(/amplitude\/power cannot reliably represent a positive channel/);});
 it('checks pure-channel conservation independently of individually matching coefficient magnitudes',()=>{const g=structuredClone(genuine_normal_slab),f=g.events[0].interface!,ts=Math.sqrt(.5/f.coefficients.flux_factor);f.coefficients.t_s=[ts,0];f.numerical_bounds.coefficient_intervals[2]=[[ts,ts],[0,0]];f.power_fractions.T_s=.5;expect(()=>decodeFresnelTrace(wire(g),{request_id:g.request_id,scene_sha256:g.scene_sha256,scene:g.scene as unknown as FresnelScene})).toThrow(/pure-channel conservation/);});
 it('retains valid raw TIR roundoff above one without clipping the returned pure-channel fraction',()=>{const g=structuredClone(genuine_tir_prism),f=g.events.find(e=>e.classification==='total_internal_reflection')!.interface!;f.power_fractions.R_p=1+Number.EPSILON;const r=decodeFresnelTrace(wire(g),{request_id:g.request_id,scene_sha256:g.scene_sha256,scene:g.scene as unknown as FresnelScene});expect(r.events.find(e=>e.classification==='total_internal_reflection')!.interface!.power_fractions.R_p).toBe(1+Number.EPSILON);});
 it('rejects a nontransverse frame at128eps independently of axis unit lengths',()=>{const g=structuredClone(genuine_normal_slab);changeFirstReflectedStates(g,s=>{s.frame.e1[1]=1e-10;s.numerical_bounds.frame_intervals[1]=[1e-10,1e-10];});expect(()=>decodeFresnelTrace(wire(g),{request_id:g.request_id,scene_sha256:g.scene_sha256,scene:g.scene as unknown as FresnelScene})).toThrow(/orthogonality/);});
 it('rejects a legitimate rotated frame attached to a different propagation direction at128eps',()=>{const g=structuredClone(genuine_normal_slab),angle=1e-10;changeFirstReflectedStates(g,s=>{s.frame.e1=[Math.cos(angle),0,Math.sin(angle)];s.frame.khat=[Math.sin(angle),0,-Math.cos(angle)];s.numerical_bounds.frame_intervals=[...s.frame.e1,...s.frame.e2,...s.frame.khat].map(n=>[n,n]);});expect(()=>decodeFresnelTrace(wire(g),{request_id:g.request_id,scene_sha256:g.scene_sha256,scene:g.scene as unknown as FresnelScene})).toThrow(/frame direction/);});
 it('admits a summed trace enclosure wider than1e-8 when individualC entries remain within1e-8',()=>{const g=structuredClone(genuine_normal_slab),count=changeFirstReflectedStates(g,s=>{const a=s.C[0],b=s.C[1];s.numerical_bounds.C_intervals[0]=[a-4e-9,a+4e-9];s.numerical_bounds.C_intervals[1]=[b-4e-9,b+4e-9];s.numerical_bounds.power_interval=[a+b-8e-9,a+b+8e-9];});expect(count).toBeGreaterThan(1);g.diagnostics.max_C_width=Math.max(...g.branches[1].initial_state.numerical_bounds.C_intervals.map(p=>p[1]-p[0]));expect(g.branches[1].initial_state.numerical_bounds.power_interval[1]-g.branches[1].initial_state.numerical_bounds.power_interval[0]).toBeGreaterThan(1e-8);expect(()=>decodeFresnelTrace(wire(g),{request_id:g.request_id,scene_sha256:g.scene_sha256,scene:g.scene as unknown as FresnelScene})).not.toThrow();});
 it('rejects an output frame norm defect above128eps even inside unchanged1e-8 certificate widths',()=>{const g=structuredClone(genuine_normal_slab),count=changeFirstReflectedStates(g,s=>{s.frame.e1[0]=1+1e-10;s.numerical_bounds.frame_intervals[0]=[1+1e-10,1+1e-10];});expect(count).toBeGreaterThan(1);expect(()=>decodeFresnelTrace(wire(g),{request_id:g.request_id,scene_sha256:g.scene_sha256,scene:g.scene as unknown as FresnelScene})).toThrow(/unit frame|orthogonality|handedness|frame direction/);});
 it('rejects a forged pure-channel fraction even when carried states and branch powers remain unchanged',()=>{const g=structuredClone(genuine_normal_slab);g.events[0].interface!.power_fractions.R_s=.5;expect(()=>decodeFresnelTrace(wire(g),{request_id:g.request_id,scene_sha256:g.scene_sha256,scene:g.scene as unknown as FresnelScene})).toThrow(/amplitude\/power/);});
 it.each([genuine_normal_slab,genuine_tir_prism])('decodes actual reflected/transmitted paths, carried states and unresolved power',g=>{const q={request_id:g.request_id,scene_sha256:g.scene_sha256,scene:g.scene as unknown as FresnelScene};const r=decodeFresnelTrace(wire(g),q);expect(r.status).toBe('incomplete');expect(r.ledger.unresolved_power).toBeGreaterThan(0);expect(r.events.some(e=>e.interface?.legs.some(l=>l.kind==='R'&&l.disposition==='allocated'))).toBe(true);expect(r.branches.length).toBeGreaterThan(1);});
 it.each([
 ['lost reflected child',(r:any)=>{r.events[0].interface.legs[0].branch_id=null;}],
 ['weak branch pruning',(r:any)=>{const leg=r.events[0].interface.legs[0];leg.disposition='exact_zero';leg.power_fraction=0;leg.state=null;leg.branch_id=null;}],
 ['wrong cumulative power',(r:any)=>{r.events[0].interface.legs[1].power_fraction=.5;}],
 ['wrong local fraction',(r:any)=>{r.events[0].interface.power_fractions.T_incident=.5;}],
 ['outgoing side sign',(r:any)=>{r.events[0].numerical_bounds.outgoing_side_intervals[0].side_interval=[-2,-1];}],
 ['foreign normal',(r:any)=>{r.events[0].interface.outward_normal=[1,0,0];}],
 ['early truncation',(r:any)=>{r.terminals.find((t:any)=>t.category==='detected').reason='interaction_cap';}],
 ['lost queue contribution',(r:any)=>{r.terminals.pop();}],
 ['duplicated parent contribution',(r:any)=>{r.terminals.push({...r.terminals[0],branch_id:'r0'});}],
 ['reset carried C',(r:any)=>{r.branches[1].initial_state.C=[.5,.5,0,0];}],
 ['wrong ancestry',(r:any)=>{r.branches[1].start_interaction_count=0;}],
 ['invented complete status',(r:any)=>{r.status='complete';}],
 ['altered infinite slab total',(r:any)=>{r.ledger.receiver_totals[0].power_fraction=12/13;}],
 ])('rejects genuine graph corrupted by %s',(_name,mutate)=>{const g=structuredClone(genuine_normal_slab);mutate(g);expect(()=>decodeFresnelTrace(wire(g),{request_id:g.request_id,scene_sha256:g.scene_sha256,scene:g.scene as unknown as FresnelScene})).toThrow();});
 it('rejects a fabricated propagating TIR child and missing phase-coefficient enclosure',()=>{for(const mutate of [(e:any)=>{e.interface.legs[1].disposition='allocated';},(e:any)=>{e.interface.numerical_bounds.coefficient_intervals[0]=null;}]){const g=structuredClone(genuine_tir_prism),e=g.events.find(e=>e.classification==='total_internal_reflection')!;mutate(e);expect(()=>decodeFresnelTrace(wire(g),{request_id:g.request_id,scene_sha256:g.scene_sha256,scene:g.scene as unknown as FresnelScene})).toThrow();}});
});
